What value does the following program print?

\u00A7\u00A7\u00A7c
#include <stdio.h>
int st[10], top = -1;
void push(int x) { st[++top] = x; }
int pop(void) { return st[top--]; }
int main(void) {
    for (int i = 1; i <= 5; i++) {
        push(i);
        if (i % 2 == 0) {
            int a = pop();
            int b = pop();
            push(a * b);
        }
    }
    int s = 0;
    while (top >= 0) s += pop();
    printf("%d\n", s);
    return 0;
}
