What does the following program print?

\u00A7\u00A7\u00A7c
#include <stdio.h>
#include <stdlib.h>
struct node { int v; struct node *next; };
struct node *push(struct node *h, int v) {
    struct node *n = malloc(sizeof *n);
    n->v = v;
    n->next = h;
    return n;
}
int main(void) {
    struct node *h = NULL;
    for (int i = 1; i <= 6; i++) h = push(h, i * i);
    struct node *p = h;
    int s = 0;
    while (p && p->next) {
        s += p->v - p->next->v;
        p = p->next->next;
    }
    printf("%d\n", s);
    return 0;
}
