The keys 42, 17, 63, 8, 25, 51, 90, 21, 30, 58, 55 are inserted in this order into an empty binary search tree, and \u00A7f\u00A7 below is called on the root. What value does it return?

\u00A7\u00A7\u00A7c
struct t { int key; struct t *l, *r; };
int f(struct t *p) {
    if (p == NULL) return 0;
    if (p->l == NULL && p->r == NULL) return 1;
    return f(p->l) + f(p->r) + (p->l != NULL && p->r != NULL);
}
