#include <stdio.h>
int main(void) {
    int a[5][5] = {
        {0, 1, 1, 0, 1},
        {1, 0, 1, 1, 0},
        {1, 1, 0, 1, 1},
        {0, 1, 1, 0, 1},
        {1, 0, 1, 1, 0}
    };
    int c = 0;
    for (int i = 0; i < 5; i++)
        for (int j = i + 1; j < 5; j++)
            for (int k = j + 1; k < 5; k++)
                if (a[i][j] && a[j][k] && a[i][k]) c++;
    printf("%d\n", c);
    return 0;
}
